query:
query GoalTransactions($id: UUID!, $startDate: Date!, $endDate: Date!, $page: PageInput) {
	goalTransactions(id: $id, startDate: $startDate, endDate: $endDate, page: $page) {
		items {
			id
			accountId
			source
			externalId
			bookingDate
			valutaDate
			bookingStatus
			amount
			currency
			counterpartyName
counterpartyDisplayName
			counterpartyIban
			description
			transactionType
			label {
				category {
					id
					slug
					name
					kind
				}
				source
				confidence
				status
				reviewReason
				proposedCategoryPath
				reasoning
			}
			splits {
				index
				amount
				category {
					id
					slug
					name
					kind
				}
			}
			tags
			transfer {
				counterpartTransactionId
				counterpartAccountId
				match
			}
			recurring {
				isRecurring
				source
				seriesId
				cadence
				medianAmount
			}
		}
		totalCount
		limit
		offset
	}
}
